/**
 * Trendz Tracker — Phase 10e Question Layout Unit Tests (tests/questionLayout.test.js)
 *
 * Verifies:
 * 1. `questionLayout(text)` returns `'nowrap'` for a 7-character text and an 18-character text,
 *    and `'wrap'` for a 19-character text.
 * 2. Representative questions generated by Division by 4, Division by 7, Day Codes, Ratio,
 *    Days to Seconds, and Prime Factor drills receive the expected layout classification
 *    and operator protection.
 */

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import {
  NOWRAP_MAX_LENGTH,
  questionLayout,
  formatQuestionText,
} from '../js/questionLayout.js';
import { DRILLS } from '../api/_drills.js';

describe('questionLayout(text) — 18-character threshold', () => {
  it('returns "nowrap" for a 7-character text ("123 / 7")', () => {
    const text7 = '123 / 7';
    assert.equal(text7.length, 7);
    assert.equal(questionLayout(text7), 'nowrap');
  });

  it('returns "nowrap" for an 18-character text', () => {
    const text18 = '123456789012345678';
    assert.equal(text18.length, 18);
    assert.equal(NOWRAP_MAX_LENGTH, 18);
    assert.equal(questionLayout(text18), 'nowrap');
  });

  it('returns "wrap" for a 19-character text', () => {
    const text19 = '05:00:00 - 15:00:00';
    assert.equal(text19.length, 19);
    assert.equal(questionLayout(text19), 'wrap');
  });

  it('trims leading and trailing whitespace before measuring length', () => {
    assert.equal(questionLayout('   72 / 4   '), 'nowrap');
    assert.equal(questionLayout('   123456789012345678   '), 'nowrap');
  });
});

describe('Drills classification & operator non-breaking behaviour', () => {
  it('classifies Division by 4, Division by 7, Day Codes, Ratio, and Prime Factor questions as "nowrap"', () => {
    const nowrapDrillKeys = [
      'divide_by_4',
      'divide_by_7',
      'day_codes',
      'ratio',
      'prime_factors',
    ];

    for (const key of nowrapDrillKeys) {
      const generated = DRILLS[key].generate();
      assert.ok(generated.length > 0, `${key} should generate questions`);
      for (const q of generated) {
        assert.ok(
          q.text.length <= 18,
          `Expected ${key} question "${q.text}" to be <= 18 chars (got ${q.text.length})`
        );
        assert.equal(
          questionLayout(q.text),
          'nowrap',
          `Expected ${key} question "${q.text}" to use nowrap`
        );
        assert.equal(formatQuestionText(q.text), q.text);
      }
    }
  });

  it('classifies Days to Seconds questions as "wrap" and binds the "-" operator with a non-breaking space so it is never left alone on a line', () => {
    const daysQuestions = DRILLS.days_to_seconds.generate();
    assert.equal(daysQuestions.length, 10);

    for (const q of daysQuestions) {
      assert.ok(
        q.text.length >= 19,
        `Expected days_to_seconds question "${q.text}" to be >= 19 chars`
      );
      assert.equal(questionLayout(q.text), 'wrap');

      const formatted = formatQuestionText(q.text);
      // The space before '-' is replaced with \u00A0 so '-' cannot wrap onto a new line by itself
      assert.ok(
        formatted.includes('\u00A0- '),
        `Expected "${formatted}" to bind "-" to the preceding token with \\u00A0`
      );
      assert.ok(
        !formatted.includes(' - '),
        `Expected "${formatted}" not to have a breakable space before "-"`
      );
    }
  });
});
